import { useState } from 'react';

export function NavMenu() {
  const [open, setOpen] = useState<string | null>(null);
  const items = {{menu_items}};
  return (
    <nav className="flex gap-4 border-b bg-white px-6">
      {items.map((m) => (
        <div key={m.label} className="relative" onMouseLeave={() => setOpen(null)}>
          <button onMouseEnter={() => setOpen(m.label)} className="py-3 text-sm hover:text-blue-600">{m.label}</button>
          {open === m.label && (
            <div className="absolute left-0 top-full z-10 w-48 rounded border bg-white py-2 shadow-lg">
              {m.children.map((c) => (
                <a key={c.href} href={c.href} className="block px-4 py-2 text-sm hover:bg-gray-100">{c.label}</a>
              ))}
            </div>
          )}
        </div>
      ))}
    </nav>
  );
}
